link.script:
window.dataLayer = window.dataLayer || [];
function gtag() { dataLayer.push(arguments); }
gtag('js', new Date());
gtag('config', 'G-QM3YBSX55C');

body.script:
			if(window.location.pathname.endsWith('/apply')) {
				var formApp = {
					data: function () {
						return {
							firstNameVal: "",
							lastNameVal: "",
							emailVal: "",
							dobDay: "",
							dobMonth: "",
							dobYear: "",
							countryVal: "",
							phoneNumberVal: "",
							addressVal: "",
							stateVal: "",
							zipVal: "",
							cityVal: "",
							declarationVal: "",
							tacVal: "",
							branchVal: "",

							formError: false,
							formErrorDescription: "",
							formSended: false,
							countries: [],
							userGeoIP: null,
							gRecaptchaResponse: ""
						}
					},
					mounted: function () {
						this.getCountriesAndBranches();
						$('.form-block').on('change keyup touchend', 'input, select', this.validateField.bind(this));
						$('.form-block .submit').on('pointerup', this.handleFormSubmit.bind(this))
						$('.form-block .clear').on('click touchend', this.handleFormClear.bind(this))
					},
					validateField: function (e) {
						var $el = $(e.target);
						var field = $el.attr('data-model');
						this[field] = $el.val();
						if (field === 'countryVal') {
							this.onCountryChange(this[field]);
						}
						$el.toggleClass('invalid', !$el[0].checkValidity());
						var $form = $el.closest('form');
						var valid = true;
						$form.find('[required]').each(function () {
							if (!$(this).val() || $(this).is('.invalid') || $(this).val() == 'off' || !$(this).val().length) {
								valid = false;
							}
						});
						if (valid) {
							$form.find('[required]').each(function () {
								$(this).toggleClass('invalid', !$(this)[0].checkValidity());
								if ($(this).is('.invalid') || $(this).val() == 'off' || !$(this).val().length) {
									valid = false;
								}
							});
						}
						$form.toggleClass('invalid', !valid);
					},
					setBranch: function (branchSelect, countryCode) {
						var country = serverCountries.find(function (_) { return _.code === countryCode; });
												if (country && country.branching) {
							var defaultBranchByCountry = {};
							// default with status 1
							defaultBranchByCountry = country.branching.find(function (item) {
								return item && item.status === '1' && item.default === true && item.branch !== '2';
								});
							if (!defaultBranchByCountry) {
								// any with status 1
								defaultBranchByCountry = country.branching.find(function (item) {
									return item && item.status === '1';
								});
								}
							var IDs = Object.keys(
								country.branching
									.filter(function (_) { return !!_.branch && _.status === '1'; })
									.map(function (_) { return _.branch; })
									.reduce(
										function (_set, branch) {
											_set[branch] = true;
											return _set;
										},
										{}
									)
							);
								this.fillBranches(serverBranches.filter(function (_) { return IDs.includes(_.ID); }))
														if (defaultBranchByCountry) {
								branchSelect.value = defaultBranchByCountry.branch;
																this.branchVal = defaultBranchByCountry.branch;
															}
						}
					},
					onCountryChange: function (countryVal) {
						this.setPhoneByCountry(this.getCountryByCode(countryVal));
						this.setBranch(branch, countryVal);
					},
					checkEmail: function (email) {
						var $def = $.Deferred();
						this.getSignToken().then(function (token) {
							$.get("https://prod-regapi.icmarkets.com/?getAction=check_branched_email&data=" + email + "&branch=12&request_from=PartnershipsForm&sign=" + token
							).done(function (data) {
								if (data && data !== 'used') {
									$def.resolve(true);
								} else {
									$def.resolve(false);
								}
							}).fail(function (e) {
								$def.resolve(false);
							});
						});
						return $def.promise();
					},
					setError: function (error) {
						error = error || 'An error has occurred';
						var errorBlock = $('.form-error-info');
						var errorBlockText = $('.form-error-info .error-description');
						var successBlock = $('.form-sended-info');
						successBlock.hide();
						errorBlock.show();
						errorBlockText.html(error);
					},
					clearResult: function () {
						var errorBlock = $('.form-error-info');
						var errorBlockText = $('.form-error-info .error-description');
						var successBlock = $('.form-sended-info');
						successBlock.hide();
						errorBlock.hide();
						errorBlockText.html('');
					},
					handleFormSubmit: function (e) {
						var self = this;
						var form = $('.form-block')[0];
						$('.form-block input').change();
						var valid = form.checkValidity();
						var buttonsBlock = $('.form-block__submit-button-block')
						var d = Number(self.dobDay);
						var m = Number(self.dobMonth);
						var y = Number(self.dobYear);
						var dob = new Date(y, m, d, 23);
						var currentDate = new Date();
						var diff = currentDate - dob;
						var diffYears = diff / (1000 * 60 * 60 * 24 * 365);
						var birthYearsValid = diffYears > 18;
						var dateValid = false;
						var gRecaptchaResponse = $('#g-recaptcha-response').val();

						// Phone validation with libphonenumber-js
						var phoneVal = self.phoneNumberVal ? self.phoneNumberVal.trim() : '';
						var phoneValid = true;
						if (phoneVal && typeof libphonenumber !== 'undefined') {
							try {
								phoneValid = libphonenumber.isValidPhoneNumber(phoneVal);
							} catch (err) {
								console.error('Phone validation error:', err);
								phoneValid = false;
							}
						}

						if (dob.getDate() === d && dob.getMonth() === m && dob.getFullYear() === y) {
							dateValid = true;
						}
							if (!self.countries) {
							return false;
						}
							var selectedCountry = self.countries.find(function (c) {
							return (c.code === self.countryVal)
						});
						var allowed = false;
						if (selectedCountry && selectedCountry.branching) {
							var branch = selectedCountry.branching.find(function (b) {
								return b.default === true && b.status === "1";
							});
							if (branch) {
								allowed = true;
							}
						}
						if (!birthYearsValid) {
							self.setError('Individuals under 18 years of age are not allowed to join.');
							setTimeout(self.clearResult, 5000);
							document.querySelector('.submit').classList.remove('disabled-style');
							return;
						}
						if (!dateValid) {
							self.setError('The date you provided is incorrect.

Please check again.');
							setTimeout(self.clearResult, 5000);
							document.querySelector('.submit').classList.remove('disabled-style');
							return;
						}
						// if (!allowed) {
						// 	self.setError('We cannot proceed with your application as it is not yet available in your region.');
						// 	setTimeout(self.clearResult, 5000);
						// 	return;
						// }
						if(!gRecaptchaResponse) {
							self.setError('Please select recaptcha');
							setTimeout(self.clearResult, 5000);
							document.querySelector('.submit').classList.remove('disabled-style');
							return;
						}
						if (phoneVal && !phoneValid) {
							$('#phone').addClass('is-invalid').addClass('invalid');
							// Error message is shown inline by phoneValidation.js
							document.querySelector('.submit').classList.remove('disabled-style');
							return;
						}
						if (form && valid && birthYearsValid && this.emailVal) {
							// Disable button now that validation passed
							var submitBtnEl = document.querySelector('.submit');
							submitBtnEl.classList.add('disabled-style');
							submitBtnEl.classList.add('submitting');
							// hide invalid validation
							this.checkEmail(this.emailVal).then(function (canContinue) {
								if (canContinue) {
									var country = self.getCountryByCode(self.countryVal) || {};
									var data = {
										first_name: self.firstNameVal,
										last_name: self.lastNameVal,
										email: self.emailVal,
										address: self.addressVal,
										state: self.stateVal,
										zip_code: self.zipVal,
										city: self.cityVal,
										country: country.name,
										phone: self.phoneNumberVal,
										submitIntroBroker: "Partnership",
										branch_id: "12",
										gRecaptchaResponse
									};
									self.onContactFormSubmit(data);
								} else {
									// Already USED or Incorrect EMAIL
									self.setError('This email address is already registered with us.

If you are a client with us, apply via the client area.');
									$('#emailaddress').toggleClass('invalid', true);
									// show invalid email validation
									setTimeout(self.clearResult, 5000);
									document.querySelector('.submit').classList.remove('disabled-style');
									document.querySelector('.submit').classList.remove('submitting');
								}
							});
						} else {
							self.setError('Please fill all required fields');
							setTimeout(self.clearResult, 5000);
							document.querySelector('.submit').classList.remove('disabled-style');
						}
					},
					handleFormClear: function (e) {
						this.formErrorDescription = "";
						this.firstNameVal = "";
						this.lastNameVal = "";
						this.emailVal = "";
						this.addressVal = "";
						this.stateVal = "";
						this.zipVal = "";
						this.cityVal = "";
						this.phoneNumberVal = "";
						this.declarationVal = "";
						this.tacVal = "";
						$('.form-block input').val('')
						if (this.userGeoIP) {
							this.countryVal = this.userGeoIP.countryCode;
							$('#country').val(this.countryVal)
							this.setPhoneByCountry(this.getCountryByCode(this.userGeoIP.countryCode));
						} else {
							this.countryVal = "AU";
						}
						this.setBranch(branch, this.countryVal);
						$('.form-block').toggleClass('invalid', true);
						if (e !== true) $('.form-sended-info').hide();
					},
					getSignToken: function () {
						var $def = $.Deferred();
						$.get('https://prod-regapi.icmarkets.com/~get~sign~token~?nocache=' + Date.now()).done(function (token) {
							$def.resolve(token);
						}).fail(function () {
							$def.resolve(null);
						});
						return $def.promise();
					},
					getCountryByCode: function (code) {
						var res = null;
						var c;
						for (var i in this.countries) {
							c = this.countries[i];
							if (c && c.code == code) {
								res = c;
								break;
							}
						} 
						return res;
					},
					getUserGeoIP: function () {
						var $def = $.Deferred();
						$.get("https://pro.ip-api.com/json/?key=xylJvTwPTjbRGfQ").done(function (done) {
							$def.resolve(done);
						}).fail(function (fail) {
							$def.reject(null);
						});
						return $def.promise();
					},
					detectUserCountry: function (filteredCountries) {
						let self = this;
						this.getUserGeoIP().then(function (userGeoIP) {
							if (userGeoIP && filteredCountries.find(function (c) { return c.code === userGeoIP.countryCode; })) {
								$('#country').val(userGeoIP.countryCode)
								self.countryVal = userGeoIP.countryCode;
								self.setBranch(branch, self.countryVal);
								self.userGeoIP = userGeoIP;
								self.setPhoneByCountry(self.getCountryByCode(userGeoIP.countryCode));
							} else {
								var fallbackCountry = filteredCountries[0];
								$('#country').val(fallbackCountry.code);
								self.countryVal = fallbackCountry.code;
								self.setBranch(branch, self.countryVal);
								self.setPhoneByCountry(fallbackCountry);
							}
						});
					},
					setPhoneByCountry: function (country) {
						if (country?.tel) {
							const cleanTel = String(country.tel).replace(/[^\d+]|(?<=.)\+/g, '');
							this.phoneNumberVal = cleanTel;
							$('#phone').val(cleanTel);
						}
					},
					getCountriesAndBranches: function () {
						let self = this;
						this.getSignToken().then(function (token) {
							$.ajax({
								dataType: "json",
								url: "https://prod-regapi.icmarkets.com/?getData&request_from=PartnershipsForm&sign=" + token,
								success: function (data) {
									window['serverCountries'] = data.countries;
									window['serverBranches'] = data.branches.filter(function (b) { return b.ID !== '2'; });
									self.fillBranches(serverBranches);
									var filteredCountries = data.countries.filter((c) => (c && c.branching && c.code !== 'AU' && c.branching.find(b => b.branch == 12 && b.status == 1)));
									self.fillCountries(filteredCountries);

									self.detectUserCountry(filteredCountries);
								},
								fail: function (err) {
									console.error('FAIL', err);
								}
							});
						});
					},
					fillCountries: function (countries) {
						this.countries = countries
						countries.forEach(function (country) {
							$('#country').append($('', {
								html: country.name,
								value: country.code,
								'data-phone': country.phone
							}))
						})
					},
					fillBranches: function (branches) {
						$('#branch').empty()
						branches.forEach(function (branch) {
							$('#branch').append($('', {
								html: branch.Name,
								value: branch.ID
							}))
						})
					},
					onContactFormSubmit: function (formInput) {
						let self = this;
						this.getSignToken().then(function (token) {
							formInput.ip = (self.userGeoIP && self.userGeoIP.query) ? self.userGeoIP.query : null;
							formInput.sign = token;
							let buttonsBlock = document.querySelector('.form-block__submit-button-block');
							if (buttonsBlock) buttonsBlock.style.display = 'none';
							$.ajax({
								type: 'POST',
								url: 'https://prod-regapi.icmarkets.com',
								dataType: "json",
								data: formInput
							}).done(function (data) {
								self.formErrorDescription = "";
								let clearButton = $('.form-block .form-block__submit-button-block .clear');
								self.formSended = true;
								if (data && data.status && data.status == "success") {
									self.formError = false;
									// $('.form-sended-info').show();
									setTimeout(function () {
										self.handleFormClear(true)
										// var link = data.link;
										// link = link.replace(/\/ \//g, '/').replace(/%2f/g, '/').replace(/%3f/g, '?');
										// link = link.replace("ReturnUrl=/OpenAccount/OpenDemoAccount", "ReturnUrl=/Requests/RequestPartner")
										// window.location = link;
										const popup = $('#popup');
										popup.addClass('d-block');
									}, 1000);
								} else {
									if (data && data.error && data.error.indexOf("ErrorMessage") !== -1) {
										var desc = JSON.parse(data.error);
										self.setError(desc["ErrorMessage"]);
									} else {
										self.setError();
									}
									setTimeout(function () {
										self.handleFormClear()
									}, 5000);
								}
							}).fail(function (error) {
								self.setError()
							});
						});
					}
				}

				$(document).ready(formApp.mounted.bind(formApp))

				$('.form-error-info .btn').click(function() {
					$('.form-error-info').hide()
				});

				$('.form-error-icon').click(function() {
					$('.form-error-info').hide()
				});
			}
